--- 获取插件列表
--- @function getPluginsInfo
--- @param app_id  应用id String 必填
--- @param hostAppInfo 宿主应用信息 json字符串:含有package_id/channel_id/user_id/user_type字段  非必填
m.getPluginsInfo = function(app_id, hostAppInfo)
    local JavaMethodName = "getPluginsInfo"
    local args = {app_id, hostAppInfo}
    local sigs = "(Ljava/lang/String;Ljava/lang/String;)V"
    m.luaj.callStaticMethod(m.JavaClassName,JavaMethodName,args,sigs)
end

