m.deleteDownloadCacheAndIgnoreSilentDownload = function(plugin_id)
    if device.platform ~= "android" then
        return
    end
    if cc.Application:getInstance():getVersion() < "1.5.9" then
        return
    end
    local JavaMethodName = "deleteDownloadCacheAndIgnoreSilentDownload"
    local args = {plugin_id}
    local sigs = "(Ljava/lang/String;)V"
    m.luaj.callStaticMethod("com/ymnsdk/replugin/RePluginSdk",JavaMethodName,args,sigs)
end

-- 插件包调用宿主包方法
m.invokeFuncNameandParameters = function(method, param)
    if device.platform ~= "android" then
        return
    end
    if type(param) == "table" then
        param = json.encode(param)
    end
    local JavaMethodName = "invokeFuncNameandParameters"
    local args = {method, param}
    local sigs = "(Ljava/lang/String;Ljava/lang/String;)V"
    print("yuhang " .. method .. "_" .. param)
    m.luaj.callStaticMethod("com/bianfeng/pluginlibrary/RePluginSdk",JavaMethodName,args,sigs)
end

return m

